<?php
require_once __DIR__.'/includes/auth.php';require_login();$cid=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$uid=current_user_id();if(!$cid||!is_member($pdo,$cid,$uid)){http_response_code(404);exit('Conversation not found. <a href="dashboard.php">Back to messages</a>');}
$st=$pdo->prepare('SELECT conversation_type,title FROM conversations WHERE conversation_id=?');$st->execute([$cid]);$conversation=$st->fetch();if(!$conversation){header('Location: dashboard.php');exit;}
if($conversation['conversation_type']==='group'){$st=$pdo->prepare('SELECT u.user_id,u.full_name,u.username,u.profile_color,u.profile_photo,u.last_seen,cm.member_role FROM conversation_members cm JOIN users u ON u.user_id=cm.user_id WHERE cm.conversation_id=? ORDER BY cm.joined_at');$st->execute([$cid]);$members=$st->fetchAll();$other=null;$title=$conversation['title'];$subtitle=count($members).' members';}
else{$st=$pdo->prepare('SELECT u.user_id,u.full_name,u.username,u.profile_color,u.profile_photo,u.last_seen FROM conversation_members cm JOIN users u ON u.user_id=cm.user_id WHERE cm.conversation_id=? AND cm.user_id<>? LIMIT 1');$st->execute([$cid,$uid]);$other=$st->fetch();if(!$other){header('Location: dashboard.php');exit;}$members=[];$title=$other['full_name'];$subtitle='@'.$other['username'].' · '.(!empty($other['last_seen'])&&strtotime($other['last_seen'])>time()-120?'Online':'Last seen '.($other['last_seen']?date('M j, H:i',strtotime($other['last_seen'])):'recently'));}
$myRole='member';$st=$pdo->prepare('SELECT member_role FROM conversation_members WHERE conversation_id=? AND user_id=?');$st->execute([$cid,$uid]);$myRole=$st->fetchColumn()?:'member';$pageTitle=$title;require __DIR__.'/includes/header.php';?>
<section class="chat-layout" id="chat-app" data-conversation-id="<?= (int)$cid ?>" data-csrf="<?= e(csrf_token()) ?>" data-current-user="<?= $uid ?>" data-group="<?= $conversation['conversation_type']==='group'?'1':'0' ?>">
<aside class="chat-sidebar"><a class="back-link" href="dashboard.php">← <span>All messages</span></a><div class="chat-person-card"><span class="avatar avatar-large" style="--avatar-color:<?= e($other['profile_color']??'#7c3aed') ?>"><?= e(strtoupper(mb_substr($title,0,1))) ?></span><h2><?= e($title) ?></h2><p><?= e($subtitle) ?></p><span class="status-label"><span class="online-dot"></span><?= $conversation['conversation_type']==='group'?'Group conversation':'Private conversation' ?></span></div><?php if($conversation['conversation_type']==='group'): ?><div class="member-list"><strong>Group members</strong><?php foreach($members as $m): ?><div class="member-mini"><?= e($m['full_name']) ?><?= $m['member_role']==='admin'?' · admin':'' ?></div><?php endforeach; ?></div><?php endif; ?><div class="sidebar-note"><span>🔒</span><p>Only members of this conversation can access its messages and files.</p></div></aside>
<section class="chat-main"><header class="chat-header"><div class="chat-header-person"><span class="avatar avatar-small" style="--avatar-color:<?= e($other['profile_color']??'#7c3aed') ?>"><?= e(strtoupper(mb_substr($title,0,1))) ?></span><div><strong><?= e($title) ?></strong><small id="chat-status"><?= e($subtitle) ?></small></div></div><a href="dashboard.php" class="icon-button mobile-back" aria-label="Back to messages">←</a></header><div class="messages-area" id="messages-area" aria-live="polite"><div class="loading-messages">Loading conversation…</div></div><div id="typing-indicator" class="typing-indicator" aria-live="polite"></div><div class="reply-preview" id="reply-preview" hidden><span id="reply-preview-text"></span><button type="button" id="cancel-reply" aria-label="Cancel reply">×</button></div><div class="chat-compose-wrap"><form id="message-form" class="message-form"><button class="icon-button compose-tool" type="button" id="emoji-toggle" title="Emoji">☺</button><label class="sr-only" for="message-input">Your message</label><textarea id="message-input" maxlength="4000" rows="1" placeholder="Write a message..."></textarea><button class="send-button" type="submit" aria-label="Send message">↑</button></form><div id="emoji-picker" class="emoji-picker" hidden>😀 😃 😄 😁 😂 🥹 😊 😍 😎 🤔 🙌 👏 👍 ❤️ 🎉 🔥 ✨ 🙏</div><div class="compose-bottom"><label class="button button-ghost button-small file-button">📎 Attach file<input type="file" id="attachment-input" hidden accept="image/*,.pdf,.doc,.docx,.txt,.zip"></label><div class="compose-hint"><span>Enter to send · Shift + Enter for a new line</span><span id="char-count">0 / 4000</span></div></div><div id="chat-error" class="chat-error" role="status"></div></div></section></section><script src="assets/js/chat.js"></script><?php require __DIR__.'/includes/footer.php'; ?>
